using FluentValidation; using JTradeERP.Application.Common.Exceptions; using JTradeERP.Application.Common.Persistence; using JTradeERP.Application.Common.Security; using JTradeERP.Domain.Security; using MediatR;
namespace JTradeERP.Application.Features.Security.Administration.AssignPermissions;
public sealed record PermissionGrantInput(Guid PermissionId,Capability Capability); public sealed record AssignPermissionsCommand(Guid RoleId,IReadOnlyCollection<PermissionGrantInput> Grants):IRequest<AssignPermissionsResponse>; public sealed record AssignPermissionsResponse(Guid RoleId,IReadOnlyCollection<PermissionGrantInput> Grants);
public sealed class AssignPermissionsValidator:AbstractValidator<AssignPermissionsCommand>{public AssignPermissionsValidator(){RuleFor(x=>x.RoleId).NotEmpty();RuleFor(x=>x.Grants).NotNull();RuleForEach(x=>x.Grants).ChildRules(g=>g.RuleFor(x=>x.Capability).IsInEnum());}}
public sealed class AssignPermissionsHandler(IApplicationDbContext db,ICurrentUserService actor):IRequestHandler<AssignPermissionsCommand,AssignPermissionsResponse>{public async Task<AssignPermissionsResponse> Handle(AssignPermissionsCommand r,CancellationToken ct){if(!db.Roles.Any(x=>x.Id==r.RoleId))throw new NotFoundException("Role was not found.");var grants=r.Grants.GroupBy(x=>x.PermissionId).Select(x=>x.Last()).ToArray();if(grants.Any(g=>!db.Permissions.Any(p=>p.Id==g.PermissionId)))throw new NotFoundException("Permission was not found.");var existing=db.RolePermissions.Where(x=>x.RoleId==r.RoleId).ToArray();var old=existing.Select(x=>$"{x.PermissionId}:{x.Capability}").ToArray();var requested=grants.ToDictionary(x=>x.PermissionId,x=>x.Capability);foreach(var rp in existing){if(!requested.TryGetValue(rp.PermissionId,out var desired)||desired==Capability.None)db.Remove(rp);else if(rp.Capability!=desired)rp.SetCapability(desired);}foreach(var g in grants.Where(x=>x.Capability!=Capability.None&&!existing.Any(oldGrant=>oldGrant.PermissionId==x.PermissionId)))db.Add(new RolePermission(r.RoleId,g.PermissionId,g.Capability));var auditNew=string.Join(',',grants.Where(x=>x.Capability!=Capability.None).Select(x=>$"{x.PermissionId}:{x.Capability}"));SecurityAuditWriter.Add(db,actor.UserId,"RolePermissionsAssigned","Role",r.RoleId.ToString(),string.Join(',',old),auditNew);await db.SaveChangesAsync(ct);return new(r.RoleId,grants);}}
public static class AssignPermissionsEndpoint{public static void Map(IEndpointRouteBuilder e)=>e.MapPut("/roles/{id:guid}/permissions",async(Guid id,AssignPermissionsCommand c,ISender s,CancellationToken t)=>Results.Ok(await s.Send(c with{RoleId=id},t))).RequirePermission("Admin.Roles.Manage",Capability.Full);}
